return {["scripts/actions/abilities/pets/sleepga.lua"]={["Path"]="scripts/actions/abilities/pets/sleepga.lua",["SHA256"]="8951f7458d523af481264f062a15f5cf60348d449c9fb9f5010875c5b76d3150",["Text"]="-----------------------------------\n-- Sleepga\n-- Family: Avatar (Shiva)\n-- Note: Ability range was increased in Sept. 6, 2016 update:\n-- https://wiki.ffo.jp/html/35741.html\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local duration = 90\n\n    local effectTable =\n    {\n        -- Does not overwrite Sleep I or Sleep II.\n        -- Does not overwrite self.\n        [1] = { effectId = xi.effect.SLEEP_I, power = 1, origin = pet, duration = duration, tier = 1, magicalElement = xi.element.DARK, bonusMacc = xi.summon.getSummoningSkillOverCap(pet) },\n    }\n\n    local messageParams =\n    {\n        messageBypass          = false,\n        messageCantGain        = xi.msg.basic.JA_NO_EFFECT,\n        messageIsImmune        = xi.msg.basic.JA_MISS,\n        messageIsTraitResisted = xi.msg.basic.JA_MISS,\n        messageIsIncompatible  = xi.msg.basic.JA_MISS,\n        messageIsResisted      = xi.msg.basic.JA_MISS,\n        messageIsNotSuccessful = xi.msg.basic.JA_MISS,\n        messageIsSuccessful    = xi.msg.basic.JA_ENFEEB_IS,\n    }\n\n    return xi.combat.action.executeMobskillStatusEffect(pet, target, petskill, effectTable, messageParams)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/slowga.lua"]={["Path"]="scripts/actions/abilities/pets/slowga.lua",["SHA256"]="3930cca66508471bdac0046ebb6edbf7e103bbc9e2100c8530561c5e5880ae0e",["Text"]="-----------------------------------\n-- Slowga\n-- Family: Avatar (Leviathan)\n-- Note: Ability range was increased in Sept. 6, 2016 update.\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local baseDuration = 180\n    local bonusTime    = utils.clamp(summoner:getSkillLevel(xi.skill.SUMMONING_MAGIC) - 300, 0, 200)\n    local duration     = baseDuration + bonusTime\n\n    local effectTable =\n    {\n        [1] = { effectId = xi.effect.SLOW, power = 3000, origin = pet, duration = duration, tier = 3, magicalElement = xi.element.EARTH, bonusMacc = xi.summon.getSummoningSkillOverCap(pet) },\n    }\n\n    local messageParams =\n    {\n        messageBypass          = false,\n        messageCantGain        = xi.msg.basic.JA_NO_EFFECT,\n        messageIsImmune        = xi.msg.basic.JA_MISS,\n        messageIsTraitResisted = xi.msg.basic.JA_MISS,\n        messageIsIncompatible  = xi.msg.basic.JA_MISS,\n        messageIsResisted      = xi.msg.basic.JA_MISS,\n        messageIsNotSuccessful = xi.msg.basic.JA_MISS,\n        messageIsSuccessful    = xi.msg.basic.JA_ENFEEB_IS,\n    }\n\n    return xi.combat.action.executeMobskillStatusEffect(pet, target, petskill, effectTable, messageParams)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/snow_cloud.lua"]={["Path"]="scripts/actions/abilities/pets/snow_cloud.lua",["SHA256"]="7def30478acd2a2240286d853d5e94e2e37f516749b77879f49acc523792fde0",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'snow_cloud_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/somersault.lua"]={["Path"]="scripts/actions/abilities/pets/somersault.lua",["SHA256"]="008517f3dea988f0ebfdb1d4e0fd4a55dc9ca39d1558b4d00b0ff686823aeced",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'somersault_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/somnolence.lua"]={["Path"]="scripts/actions/abilities/pets/somnolence.lua",["SHA256"]="1c998efb5ac2cb263659cdbdbeb1781e830ca4dbdbfb983ce9ea87e99f3c46e9",["Text"]="-----------------------------------\n-- Somnolence\n-- Family: Avatar (Diabolos)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage     = pet:getMainLvl() + 2\n    params.fTP            = { 2.0, 2.0, 2.0 }\n    params.element        = xi.element.DARK\n    params.attackType     = xi.attackType.MAGICAL\n    params.damageType     = xi.damageType.DARK\n    params.shadowBehavior = xi.mobskills.shadowBehavior.NUMSHADOWS_1 -- TODO: Capture shadowBehavior\n    params.canMagicBurst  = true\n    params.primaryMessage = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobMagicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n\n        local duration = 120 -- TODO: Capture retail baseDuration.\n\n        local effectTable =\n        {\n            -- TODO: Is effect element Wind or Dark?\n            [1] = { effectId = xi.effect.WEIGHT, power = 50, duration = duration, magicalElement = xi.element.WIND },\n        }\n\n        xi.combat.action.executeMobskillStatusEffect(pet, target, petskill, effectTable, { messageBypass = true })\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/sonic_buffet.lua"]={["Path"]="scripts/actions/abilities/pets/sonic_buffet.lua",["SHA256"]="05b6d4d003a321274ffae21a36dcf40ed65be791a5f8ad17a059059dc77dab58",["Text"]="-----------------------------------\n-- Sonic Buffet\n-- Family: Siren (Player Pet)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\n-- http://wiki.ffo.jp/html/37931.html\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage      = pet:getMainLvl() + 2\n    -- TODO: upon smn BP damage rewrite, the base damage & mods etc need to be re-evaluated.\n    -- fTP starts at 2.0 and scales every 150 tp by .1 for a range of 2.0 to 4.0. Base value ballparked from retail.\n    params.fTP             = { 2.0, 3.0, 4.0 }\n    params.int_wSC         = 0.30\n    params.element         = xi.element.WIND\n    params.attackType      = xi.attackType.MAGICAL\n    params.damageType      = xi.damageType.WIND\n    params.shadowBehavior  = xi.mobskills.shadowBehavior.NUMSHADOWS_1 -- TODO: Capture shadowBehavior\n    params.dStatMultiplier = 1.5\n    params.canMagicBurst   = true\n    params.primaryMessage  = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobMagicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    -- Note: This dispel is Wind based rather than Dark.\n    local maccParams =\n    {\n        effectId       = xi.effect.NONE,\n        magicalElement = xi.element.WIND,\n        bonusMacc      = xi.summon.getSummoningSkillOverCap(pet),\n        actorStat      = xi.mod.INT,\n    }\n\n    local resist = xi.combat.magicHitRate.calculateResistRate(pet, target, maccParams)\n    if resist >= 0.5 then\n        target:dispelStatusEffect()\n    end\n\n    pet:setTP(0) -- Not possible to get Occult Acumen on avatars yet, so unable to determine if magical BPs can return TP.\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/soothing_current.lua"]={["Path"]="scripts/actions/abilities/pets/soothing_current.lua",["SHA256"]="37e689da1b189a67932aed5a939303c0abf568606b27498b750623225c2ba72d",["Text"]="-----------------------------------\n-- Soothing Current\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    if target:addStatusEffect(xi.effect.CURING_CONDUIT, { power = 15, duration = 180, origin = pet }) then\n        if target:getID() == action:getPrimaryTargetID() then\n            petskill:setMsg(xi.msg.basic.SKILL_GAIN_EFFECT_2)\n        else\n            petskill:setMsg(xi.msg.basic.JA_GAIN_EFFECT)\n        end\n    else\n        petskill:setMsg(xi.msg.basic.JA_NO_EFFECT_2)\n        return\n    end\n\n    return xi.effect.CURING_CONDUIT\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/soothing_ruby.lua"]={["Path"]="scripts/actions/abilities/pets/soothing_ruby.lua",["SHA256"]="de73d3822bc136728aa38ef427b385ae6b1ced091632064de519ba49c4d9666f",["Text"]="-----------------------------------\n-- Soothing Ruby\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n    return xi.job_utils.summoner.useSoothingRuby(target, pet, petskill, summoner, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/soporific.lua"]={["Path"]="scripts/actions/abilities/pets/soporific.lua",["SHA256"]="e488e54494d7ef8d236988452bb58a8a03dda38e9877490e6c7588a2ae9a48aa",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'soporific_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/spinning_dive.lua"]={["Path"]="scripts/actions/abilities/pets/spinning_dive.lua",["SHA256"]="2c0cc23197fb381288dbcf33c07e42e1fc664661374f01c5028fda09af757abc",["Text"]="-----------------------------------\n-- Spinning Dive\n-- Family: Avatar (Leviathan)\n-- Description: Deals physical damage to a target.\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 1\n    params.fTP               = { 7.01171, 7.01171, 7.01171 }\n    params.fTPSubsequentHits = { 7.01171, 7.01171, 7.01171 }\n    params.str_wSC           = 0.30\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.SLASHING\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    params.attackMultiplier = { 2.0, 2.0, 2.0 }\n    -- params.accuracyModifier = { 0, 0, 0 } TODO: Capture accuracy\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/spinning_top.lua"]={["Path"]="scripts/actions/abilities/pets/spinning_top.lua",["SHA256"]="164beceb7b944e3719eb78002e24c67c8e36aa3951914c0e7af6e518d128a0a2",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'spinning_top_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/spiral_spin.lua"]={["Path"]="scripts/actions/abilities/pets/spiral_spin.lua",["SHA256"]="65048bbaccec4713cb19df5d833f4d1f48334aee9ff09781bce26ef601aea859",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'spiral_spin_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/spoil.lua"]={["Path"]="scripts/actions/abilities/pets/spoil.lua",["SHA256"]="b2ec5a5b3fbb0a0c1fd11d271e69df821b0fc9c4d7da16668e31efeec6a5bae3",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'spoil_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/spore.lua"]={["Path"]="scripts/actions/abilities/pets/spore.lua",["SHA256"]="2d6fe1e6111e5095f7863db5acc18946e40a09015be2ca477cbc79a12bc257e1",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'spore_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/spring_water.lua"]={["Path"]="scripts/actions/abilities/pets/spring_water.lua",["SHA256"]="978b6f942388bd642f4ab9494db9d6a7b3a40049b2bb4b8864061d6714c5f0c8",["Text"]="-----------------------------------\n-- Spring Water\n-- Family: Avatar (Leviathan)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    -- TODO: Ability range scales with TP.\n\n    local removableEffects =\n    {\n        xi.effect.BLINDNESS,\n        xi.effect.DISEASE,\n        xi.effect.PARALYSIS,\n        xi.effect.PETRIFICATION,\n        xi.effect.POISON,\n        xi.effect.SILENCE,\n        -- TODO: JPWiki mentions that Spring Water can remove Mute inflicted by Promathia. Need captures.\n        -- Mute inflicted from Eight of Cups mob could not be removed by this skill.\n    }\n\n    local activeEffects = {}\n\n    -- Fetch list of removable effects currently on target\n    for _, effectId in ipairs(removableEffects) do\n        if target:getStatusEffect(effectId) then\n            table.insert(activeEffects, effectId)\n        end\n    end\n\n    -- Remove one removable effect from the target, chosen at random\n    if #activeEffects > 0 then\n        activeEffects = utils.shuffle(activeEffects)\n\n        target:delStatusEffect(activeEffects[1])\n    end\n\n    local params = {}\n\n    params.baseHeal       = pet:getMainLvl() * 8 - 152\n    params.primaryMessage = xi.msg.basic.JA_RECOVERS_HP_2\n\n    return xi.mobskills.mobHealMove(pet, target, petskill, action, params)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/stone_ii.lua"]={["Path"]="scripts/actions/abilities/pets/stone_ii.lua",["SHA256"]="4b2f07c320f4ac7fb7004209a50f8b9d78362cf25674a3ae493f920bebd63b7c",["Text"]="-----------------------------------\n-- Stone II\n-- Family: Titan (Player Pet)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage      = pet:getMainLvl() + 2\n    params.fTP             = { 1.500, 2.750, 3.125 }\n    params.int_wSC         = 0.30\n    params.element         = xi.element.EARTH\n    params.attackType      = xi.attackType.MAGICAL\n    params.damageType      = xi.damageType.EARTH\n    params.shadowBehavior  = xi.mobskills.shadowBehavior.IGNORE_SHADOWS\n    params.dStatMultiplier = 1.5\n    params.canMagicBurst   = true\n    params.primaryMessage  = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobMagicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/stone_iv.lua"]={["Path"]="scripts/actions/abilities/pets/stone_iv.lua",["SHA256"]="15fd22982d70317c8c4f4d4c68a8b0f2d4f7d4dd63fd8ba9d81b5445238a8d0d",["Text"]="-----------------------------------\n-- Stone IV\n-- Family: Titan (Player Pet)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage      = pet:getMainLvl() + 2\n    params.fTP             = { 3.6250, 5.3125, 6.1250 }\n    params.int_wSC         = 0.30\n    params.element         = xi.element.EARTH\n    params.attackType      = xi.attackType.MAGICAL\n    params.damageType      = xi.damageType.EARTH\n    params.shadowBehavior  = xi.mobskills.shadowBehavior.IGNORE_SHADOWS\n    params.dStatMultiplier = 1.5\n    params.canMagicBurst   = true\n    params.primaryMessage  = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobMagicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/suction.lua"]={["Path"]="scripts/actions/abilities/pets/suction.lua",["SHA256"]="04fc4280cfafbbd979175349f5b1bce74ebcf0cefcef95c96740e2a7245db66d",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'suction_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/sudden_lunge.lua"]={["Path"]="scripts/actions/abilities/pets/sudden_lunge.lua",["SHA256"]="83d90d21591670ad3369ee6ed4bcf6c99450f2b25be5158eaa8bc6419ecf4a25",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'sudden_lunge_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/super_climb.lua"]={["Path"]="scripts/actions/abilities/pets/super_climb.lua",["SHA256"]="85b865d08a18a7ec0ea3c5ef31bbfa6aeb4d992c3d12c9d7193d4fd254703dcd",["Text"]="-----------------------------------\n-- Ability: Super Climb\n-- Used by the Wyvern when the Dragoon uses Super Jump.\n-- Does not shed hate, but allows the wyvern to dodge any attack like the Dragoon.\n-- Obtained: Dragoon Level 50\n-- Duration: Instant\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    pet:queue(0, function(petArg)\n        petArg:untargetableAndUnactionable(5000)\n    end)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/tail_blow.lua"]={["Path"]="scripts/actions/abilities/pets/tail_blow.lua",["SHA256"]="3c6a233a843752564b9b4c8ff30c7dcd8dd67c5eff2ffdd859d620465ebef2f9",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'tail_blow_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/tail_whip.lua"]={["Path"]="scripts/actions/abilities/pets/tail_whip.lua",["SHA256"]="85b5ff497359f8c1b1a422637cbc3ed4c9e79ee274ef8f2424edc88f0ee4e70c",["Text"]="-----------------------------------\n-- Tail Whip\n-- Family: Avatar (Leviathan)\n-- Description: Deals physical damage to a target. Additional Effect: Weight\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 1\n    params.fTP               = { 3.0, 3.0, 3.0 } -- TODO: Capture fTPs for 2000/3000 TP\n    params.fTPSubsequentHits = { 3.0, 3.0, 3.0 }\n    params.str_wSC           = 0.30\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.BLUNT\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    params.attackMultiplier  = { 2.0, 2.0, 2.0 }\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n\n        local effectTable =\n        {\n            [1] = { effectId = xi.effect.WEIGHT, power = 50, duration = 120, tier = 1 }, -- TODO: Capture power/duration/tier\n        }\n\n        xi.combat.action.executeMobskillStatusEffect(pet, target, petskill, effectTable, { messageBypass = true })\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/thunder_ii.lua"]={["Path"]="scripts/actions/abilities/pets/thunder_ii.lua",["SHA256"]="c9849d0edc09355b257235979ce660ad8d6e2ecc3dbecbeb278a74112b8bc22a",["Text"]="-----------------------------------\n-- Thunder II\n-- Family: Ramuh (Player Pet)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage      = pet:getMainLvl() + 2\n    params.fTP             = { 1.500, 2.750, 3.125 }\n    params.int_wSC         = 0.30\n    params.element         = xi.element.THUNDER\n    params.attackType      = xi.attackType.MAGICAL\n    params.damageType      = xi.damageType.THUNDER\n    params.shadowBehavior  = xi.mobskills.shadowBehavior.IGNORE_SHADOWS\n    params.dStatMultiplier = 1.5\n    params.canMagicBurst   = true\n    params.primaryMessage  = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobMagicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/thunder_iv.lua"]={["Path"]="scripts/actions/abilities/pets/thunder_iv.lua",["SHA256"]="b2aca4f7ed68a9011068bb732b0f898237029222d913e3cea5babdd4a3e62c7b",["Text"]="-----------------------------------\n-- Thunder IV\n-- Family: Ramuh (Player Pet)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage      = pet:getMainLvl() + 2\n    params.fTP             = { 3.6250, 5.3125, 6.1250 }\n    params.int_wSC         = 0.30\n    params.element         = xi.element.THUNDER\n    params.attackType      = xi.attackType.MAGICAL\n    params.damageType      = xi.damageType.THUNDER\n    params.shadowBehavior  = xi.mobskills.shadowBehavior.IGNORE_SHADOWS\n    params.dStatMultiplier = 1.5\n    params.canMagicBurst   = true\n    params.primaryMessage  = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobMagicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/thunderspark.lua"]={["Path"]="scripts/actions/abilities/pets/thunderspark.lua",["SHA256"]="f3dd9fa1c5f9501f8990f37efd09776808d773cf5fae2c7d288c5a7d3298501e",["Text"]="-----------------------------------\n-- Thunderspark\n-- Family: Ramuh (Player Pet)\n-- Note: Ability range was increased in Sept. 6, 2016 update:\n-- https://wiki.ffo.jp/html/35741.html\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage      = pet:getMainLvl() + 2\n    params.fTP             = { 2.500, 3.000, 3.246 }\n    params.int_wSC         = 0.30\n    params.element         = xi.element.THUNDER\n    params.attackType      = xi.attackType.MAGICAL\n    params.damageType      = xi.damageType.THUNDER\n    params.shadowBehavior  = xi.mobskills.shadowBehavior.NUMSHADOWS_1 -- TODO: Capture shadowBehavior\n    params.dStatMultiplier = 1.5\n    params.canMagicBurst   = true\n    params.primaryMessage  = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobMagicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n\n        xi.mobskills.mobStatusEffectMove(pet, target, xi.effect.PARALYSIS, 15, 0, 60)\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/thunderstorm.lua"]={["Path"]="scripts/actions/abilities/pets/thunderstorm.lua",["SHA256"]="f3eb35671f69d7d4f272bfeeddb2d2c7ad1c1ae41ae599821b612a46d150e8f2",["Text"]="-----------------------------------\n-- Thunderstorm\n-- Family: Ramuh (Player Pet)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    -- Merit TP bonus.\n    local merits = 0\n\n    if summoner and summoner:isPC() then\n        merits = utils.clamp(summoner:getMerit(xi.merit.THUNDERSTORM) - 400, 0, 3000)\n    end\n\n    local params = {}\n\n    params.baseDamage      = pet:getMainLvl() + 2\n    params.fTP             = { 5.3570, 8.0273, 10.7031 }\n    params.fTPBonus        = merits\n    params.int_wSC         = 0.30\n    params.element         = xi.element.THUNDER\n    params.attackType      = xi.attackType.MAGICAL\n    params.damageType      = xi.damageType.THUNDER\n    params.shadowBehavior  = xi.mobskills.shadowBehavior.NUMSHADOWS_1 -- TODO: Capture shadowBehavior\n    params.dStatMultiplier = 1.5\n    params.canMagicBurst   = true\n    params.primaryMessage  = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobMagicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/tidal_roar.lua"]={["Path"]="scripts/actions/abilities/pets/tidal_roar.lua",["SHA256"]="e4b4dc8586b2fdd13a90353ce8b97d7f0a5fe6dc2a743cfa88ecf2c65805b96c",["Text"]="-----------------------------------\n-- Tidal Roar\n-- Family: Avatar (Leviathan)\n-- https://wiki.ffo.jp/html/21081.html\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local baseDuration = 60 -- TODO: Capture baseDuration\n    local bonusTime    = utils.clamp(summoner:getSkillLevel(xi.skill.SUMMONING_MAGIC) - 300, 0, 200)\n    local duration     = baseDuration + bonusTime\n\n    local effectTable =\n    {\n        -- TODO: Capture Tier\n        -- TODO: Research how half resists are handled\n        [1] = { effectId = xi.effect.ATTACK_DOWN, power = 25, origin = pet, duration = duration, tier = 1, magicalElement = xi.element.WATER },\n    }\n\n    local messageParams =\n    {\n        messageBypass          = false,\n        messageCantGain        = xi.msg.basic.JA_NO_EFFECT,\n        messageIsImmune        = xi.msg.basic.JA_MISS,\n        messageIsTraitResisted = xi.msg.basic.JA_MISS,\n        messageIsIncompatible  = xi.msg.basic.JA_MISS,\n        messageIsResisted      = xi.msg.basic.JA_MISS,\n        messageIsNotSuccessful = xi.msg.basic.JA_MISS,\n        messageIsSuccessful    = xi.msg.basic.JA_ENFEEB_IS,\n    }\n\n    return xi.combat.action.executeMobskillStatusEffect(pet, target, petskill, effectTable, messageParams)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/tidal_wave.lua"]={["Path"]="scripts/actions/abilities/pets/tidal_wave.lua",["SHA256"]="23748033a82f45bacc6dfeede418f29a9faabd7e72ee765c9ce033242ddb6fde",["Text"]="-----------------------------------\n-- Tidal Wave\n-- Family: Leviathan (Player Pet)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage      = pet:getMainLvl() + 2\n    params.fTP             = { 9.0, 9.0, 9.0 }\n    params.int_wSC         = 0.30\n    params.element         = xi.element.WATER\n    params.attackType      = xi.attackType.MAGICAL\n    params.damageType      = xi.damageType.WATER\n    params.shadowBehavior  = xi.mobskills.shadowBehavior.NUMSHADOWS_1 -- TODO: Capture shadowBehavior\n    params.dStatMultiplier = 1.5\n    params.canMagicBurst   = true\n    params.primaryMessage  = xi.msg.basic.USES_JA_TAKE_DAMAGE\n    -- TODO: Should not consume TP\n\n    local info = xi.mobskills.mobMagicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    summoner:setMP(0)\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/tornado_ii.lua"]={["Path"]="scripts/actions/abilities/pets/tornado_ii.lua",["SHA256"]="678de4bd348af70ac92c7392be451050f667442224c2845a016a277247497f40",["Text"]="-----------------------------------\n-- Tornado II\n-- Family: Siren (Player Pet)\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.summoner.canUseBloodPact(player, player:getPet(), target, ability)\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage      = pet:getMainLvl() + 2\n    params.fTP             = { 6.0000, 7.6875, 8.5000 } -- Values from JPWiki\n    params.int_wSC         = 0.30\n    params.element         = xi.element.WIND\n    params.attackType      = xi.attackType.MAGICAL\n    params.damageType      = xi.damageType.WIND\n    params.shadowBehavior  = xi.mobskills.shadowBehavior.IGNORE_SHADOWS\n    params.dStatMultiplier = 1.5\n    params.canMagicBurst   = true\n    params.primaryMessage  = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobMagicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    pet:setTP(0) -- not possible to get Occult Acumen on avatars yet, so unable to determine if magical BPs can return TP.\n\n    return info.damage\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/tortoise_stomp.lua"]={["Path"]="scripts/actions/abilities/pets/tortoise_stomp.lua",["SHA256"]="c6cdcf05320915ccf692da6df192e546bcbbe961a59ad1c48080b6b38dbaa7a6",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'tortoise_stomp_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/toxic_spit.lua"]={["Path"]="scripts/actions/abilities/pets/toxic_spit.lua",["SHA256"]="606f0175d00526a3d8884c04a543a6a69db27652eb50a66b5da4ad5570fe47eb",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'toxic_spit_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/pets/tp_drainkiss.lua"]={["Path"]="scripts/actions/abilities/pets/tp_drainkiss.lua",["SHA256"]="0909b0008a6b85c867461f570154eeaa760c5f9520d1de73690d02371cef5a7a",["Text"]="-----------------------------------\n-- Generic jug pet skill\n-- TODO: verify functionality with regards to jug pet differences from regular mobs\n-----------------------------------\n---@type TAbilityPet\nlocal abilityObject = {}\nlocal skillName = 'tp_drainkiss_jugpet'\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0\nend\n\nabilityObject.onPetAbility = function(target, pet, petskill, owner, action)\n    local result = xi.actions.mobskills[skillName].onMobWeaponSkill(pet, target, petskill, action)\n\n    return result\nend\n\nreturn abilityObject\n"}};
